"""The tp4/np1-fastlane window pack (scripts/ci/references/fusion-jobs/NP1, generated by make_np1_jobs.py), the smoke shapes it runs and the report that reads its ABAB.

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; every NEEDS line names earlier jobs; every serving job carries the two Swift checkpoint
keys and the same profile as its pair partner but for the flag; every smoke job runs a profile of the lone-user family with the smoke tests the eight-seat rule requires; every template parses through
the job reader with rc 0; the pack is what the generator makes; nothing in it names a host, an address or a registry. The smoke shapes np1_live1/2/4 run for real against test_levern_smoke's fake server
and np1_report reads an ABAB of fake logs the way octo3_report reads the octo ones."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import c2_smoke_check as check  # noqa: E402
import make_np1_jobs as pack  # noqa: E402
import np1_report as report  # noqa: E402
from test_levern_smoke import SmokeRuns  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]

# job -> (mode, serves Swift, profile, smoke tests)
EXPECTED = {
    'B0-build-window': ('stop', False, '', ''),
    'X0-status-rescan-reset': ('stop', False, '', ''),
    'A1-np1-audited-attach': ('stop', True, pack.AUDIT, pack.AUDIT_TESTS),
    'C1-control-a': ('soft', True, pack.SHIP, pack.TIMED_TESTS),
    'L1-np1-a': ('soft', True, pack.ARM, pack.TIMED_TESTS),
    'C2-control-b': ('soft', True, pack.SHIP, pack.TIMED_TESTS),
    'L2-np1-b': ('soft', True, pack.ARM, pack.TIMED_TESTS),
    'Z-reset': ('soft', False, '', ''),
}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_order_lists_exactly_the_folders_templates_once_on_one_image(self):
        rows = order_lines()
        self.assertEqual([row[0] for row in rows], list(EXPECTED), 'in value order')
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual({row[2] for row in rows}, {pack.IMAGE})
        self.assertEqual(pack.IMAGE, 'tp4-np1-1', 'the placeholder tag of the brief')
        for row in rows:
            self.assertEqual(row[1], EXPECTED[row[0]][0], row[0])
            self.assertEqual(values(row[0])['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_header_total_matches_the_minutes(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        minutes = sum(int(row[3]) for row in order_lines())
        self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text)
        for row in order_lines():
            self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text)

    def test_needs_lines_name_earlier_jobs_only(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        for left_right in directives('# NEEDS '):
            arrow = left_right.index('<-')
            left, right = left_right[:arrow], left_right[arrow + 1:]
            for job_name in left + right:
                self.assertIn(job_name, names)
            for later in left:
                for earlier in right:
                    self.assertLess(names.index(earlier), names.index(later), left_right)
        needed = set(token for line in directives('# NEEDS ') for token in line[:line.index('<-')])
        self.assertTrue({'X0', 'A1', 'C1', 'L1', 'C2', 'L2'} <= needed)
        self.assertEqual(directives('# NEEDS ')[1:2], [['A1', '<-', 'X0']])

    def test_the_arc_range_covers_the_audited_boot_and_every_timed_job_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        (first, last), = directives('# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'L2'))
        for token in ('A1', 'C1', 'L1', 'C2', 'L2'):
            self.assertTrue(names.index(first) <= names.index(token) <= names.index(last), token)
        for token in ('B0', 'X0', 'Z'):
            self.assertFalse(names.index(first) <= names.index(token) <= names.index(last), token)

    def test_no_tag_is_pushed_from_the_branch_and_the_order_says_what_is_new_on_the_device(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('Never cancel a running card job', 'THE ONE NEW DEVICE FACT', '557,056', 'UNQUALIFIED', 'owner traffic waiver'):
            self.assertIn(phrase, text)
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                self.assertEqual(code, 0, text)

    def test_serving_jobs_carry_the_checkpoint_keys_and_the_expected_profile_and_tests(self):
        for name, (_mode, serves_swift, profile, tests) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)

    def test_the_outputs_the_workflow_reads(self):
        for name, (_mode, serves_swift, _profile, _tests) in EXPECTED.items():
            code, text = run_reader(PACK / (name + '.env'))
            outputs = dict(line.split('=', 1) for line in text.splitlines() if '=' in line)
            with self.subTest(name=name):
                self.assertEqual(outputs['model_repo'], SWIFT['repo'] if serves_swift else '')

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name, (_mode, _swift, profile, tests) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', tests.split(','))
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_no_job_uses_a_step_that_does_not_forward_the_checkpoint(self):
        for name in EXPECTED:
            actions = set(values(name)['C2_ACTIONS'].split())
            if values(name).get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            self.assertFalse(actions & {'gate', 'prefix', 'replay', 'push', 'agentstop', 'agentstart', 'unserve', 'platform'}, name)

    def test_the_build_bakes_the_approved_ship_profile_with_the_oneq_graft_and_never_a_twin(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP, 'K64j-OQ'))
        entry = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][pack.SHIP]
        self.assertFalse(job.bake_waiver_pending(entry), 'the ship-4 waiver is APPROVED: the build is not refused')
        self.assertNotIn(pack.ARM, json.dumps(found))
        for name in EXPECTED:
            if name != 'B0-build-window':
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_decode_pairs_differ_by_the_profile_alone_and_the_control_is_the_approved_profile(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        for control, arm in (('C1-control-a', 'L1-np1-a'), ('C2-control-b', 'L2-np1-b')):
            self.assertEqual([values(control)[key] for key in keys], [values(arm)[key] for key in keys])
            self.assertEqual((values(control)['C2_PROFILE'], values(arm)['C2_PROFILE']), (pack.SHIP, pack.ARM))
        self.assertEqual(values('C1-control-a')['C2_SMOKE_TESTS'], 'warmup,np1_live1,np1_live2,np1_live4,concurrent8_steady')

    def test_the_audited_attach_runs_the_audit_twin_and_the_shapes_that_put_one_user_alone(self):
        found = values('A1-np1-audited-attach')
        self.assertEqual(found['C2_PROFILE'], pack.AUDIT)
        self.assertEqual(found['C2_SMOKE_TESTS'], 'warmup,coding,np1_live2,concurrent5_split,concurrent8_drain,concurrent8_steady')
        self.assertLessEqual(int(found['C2_BOX_MINUTES']), 210)
        self.assertGreater(int(found['C2_BOX_MINUTES']), int(order_lines()[2][3]), 'the box is longer than the estimate')

    def test_the_templates_name_the_lines_the_arms_log(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'L1-np1-a.env').read_text(encoding='utf-8'))
        for phrase in ('[NP1] kv scratch:', '[SOLO-PACKED] admitted min_users=1 scratch_pages=16500', 'packed padded block admitted min_users=1 users=4 max_idle=4', 'np1_report.py', 'octo_compare.py',
                       'octo_judge.py'):
            self.assertIn(phrase, text)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')


class SmokeShapeTests(SmokeRuns):
    """np1_live1, np1_live2 and np1_live4 against the fake server: the first N steady prompts, started together, each to exactly 2,000 tokens with ignore_eos."""

    def test_each_shape_sends_its_users_at_the_fixed_budget_and_registers_as_an_opt_in_test(self):
        source = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        for count in (1, 2, 4):
            self.assertIn("'np1_live%d': %d" % (count, count), source, 'in SHAPE_SEATS')
            results, chats, _completions, _tokenized, _ = self.ran('np1_live%d' % count)
            entry = results['np1_live%d' % count]
            with self.subTest(count=count):
                self.assertNotIn('error', entry, {key: value for key, value in entry.items() if key != 'users'})
                self.assertEqual(len(entry['users']), count)
                self.assertEqual(len(chats), count, 'never a request more than the live seats asked')
                self.assertEqual({chat['body']['max_tokens'] for chat in chats}, {2000})
                self.assertTrue(all(chat['body'].get('ignore_eos') for chat in chats))
                self.assertEqual(len({chat['body']['messages'][0]['content'] for chat in chats}), count, 'different prompts')
                self.assertEqual(check.smoke_problems(results), [])
        self.assertEqual(pack.TIMED_TESTS.split(','), ['warmup', 'np1_live1', 'np1_live2', 'np1_live4', 'concurrent8_steady'])

    def test_the_prompts_are_the_first_of_the_eight_seat_steady_test(self):
        _results, one, _c, _t, _ = self.ran('np1_live1')
        _results, four, _c, _t, _ = self.ran('np1_live4')
        self.assertEqual(sorted(chat['body']['messages'][0]['content'] for chat in one)[0] in [chat['body']['messages'][0]['content'] for chat in four], True)


def window(rate, seconds=30.0):
    return dict(aggregate=dict(live4_agg_tok_s=rate, live4_min_tok_s=rate, live4_window_s=seconds), users=[])


def log(rates):
    return {test: window(rate) for test, rate in rates.items()}


class ReportTests(unittest.TestCase):
    def rates(self, one, two, four, eight):
        return log({'np1_live1': one, 'np1_live2': two, 'np1_live4': four, 'concurrent8_steady': eight})

    def test_a_lone_user_that_doubles_and_everything_else_level_is_go(self):
        control, arm = self.rates(37.0, 188.0, 380.0, 700.0), self.rates(94.0, 188.5, 379.0, 702.0)
        again_control, again_arm = (self.rates(*[rate * 1.02 for rate in rates]) for rates in ((37.0, 188.0, 380.0, 700.0), (94.0, 188.5, 379.0, 702.0)))     # the second boot drifts 2%
        rows, go, notes = report.read(control, arm, again_control, again_arm)
        self.assertTrue(go, notes)
        self.assertEqual({row['test']: row['verdict'] for row in rows}, {'np1_live1': 'GAIN', 'np1_live2': 'PARITY', 'np1_live4': 'PARITY', 'concurrent8_steady': 'PARITY'})

    def test_a_loss_at_eight_seats_or_no_gain_at_one_is_no_go(self):
        control = self.rates(37.0, 188.0, 380.0, 700.0)
        for arm, word in ((self.rates(94.0, 188.0, 380.0, 600.0), 'concurrent8_steady'), (self.rates(37.5, 188.0, 380.0, 700.0), 'np1_live1')):
            rows, go, notes = report.read(control, arm, control, arm)
            with self.subTest(word=word):
                self.assertFalse(go)
                self.assertTrue(any(word in note for note in notes) or any(row['test'] == word and row['verdict'] != 'GAIN' for row in rows), (notes, rows))

    def test_a_window_too_short_to_read_is_unread_not_a_pass(self):
        control = self.rates(37.0, 188.0, 380.0, 700.0)
        arm = dict(control, np1_live1=window(94.0, seconds=4.0))
        rows, go, notes = report.read(control, arm, control, arm)
        self.assertIsNone(go)
        self.assertEqual(rows[0]['verdict'], 'UNREAD')

    def test_the_boot_to_boot_floor_keeps_a_noisy_pair_from_reading_as_a_gain(self):
        control_a = self.rates(37.0, 188.0, 380.0, 700.0)
        control_b = self.rates(41.0, 188.0, 380.0, 700.0)         # the control itself moved 10% between boots
        arm_a = self.rates(42.0, 188.0, 380.0, 700.0)
        arm_b = self.rates(45.0, 188.0, 380.0, 700.0)
        rows, go, notes = report.read(control_a, arm_a, control_b, arm_b)
        self.assertEqual(rows[0]['verdict'], 'PARITY')
        self.assertFalse(go)

    def test_the_tests_it_reads_are_the_smoke_shapes_the_pack_runs(self):
        self.assertEqual(report.TESTS[:3], ('np1_live1', 'np1_live2', 'np1_live4'))
        self.assertEqual(set(report.TESTS) - set(pack.TIMED_TESTS.split(',')), set())
        self.assertEqual(report.ACTS_ON, 'np1_live1')


if __name__ == '__main__':
    unittest.main()
